package com.bank.contract;

import com.bank.contract.gen.*;      // ← generated by protoc from transfer.proto
import io.grpc.stub.StreamObserver;
import java.math.BigDecimal;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

// We EXTEND the generated base class. The compiler forces our method signatures
// to match the contract EXACTLY — that is compile-time enforcement.
public class AccountServiceImpl extends TransferServiceGrpc.TransferServiceImplBase {
    private static final Logger log = Logger.getLogger(AccountServiceImpl.class.getName());
    private final Map<String, BigDecimal> balances = new ConcurrentHashMap<>(Map.of(
        "SAV2001", new BigDecimal("1000000"),   // Rajesh
        "CUR3001", new BigDecimal("250000")));    // Priya

    @Override
    public void transfer(TransferRequest req, StreamObserver<TransferResponse> obs) {
        BigDecimal amount = new BigDecimal(req.getAmount());    // typed getter, generated
        log.info(() -> "Transfer Rs." + amount + " " + req.getFromAccount()
            + "->" + req.getToAccount());
        balances.put(req.getFromAccount(), balances.get(req.getFromAccount()).subtract(amount));
        balances.merge(req.getToAccount(), amount, BigDecimal::add);
        obs.onNext(TransferResponse.newBuilder()          // typed builder, generated
            .setTransferId("TXF-" + UUID.randomUUID())
            .setStatus("COMPLETED")
            .setFromBalance(balances.get(req.getFromAccount()).toString())
            .build());
        obs.onCompleted();
    }
}
