package com.bank.contract;

import com.bank.contract.gen.*;
import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import java.util.logging.Logger;

public class TransferClient {
    private static final Logger log = Logger.getLogger(TransferClient.class.getName());
    public static void main(String[] args) {
        ManagedChannel channel = ManagedChannelBuilder
            .forAddress("localhost", 9090).usePlaintext().build();
        // Generated blocking stub: if the contract changed, THIS would fail to compile.
        TransferServiceGrpc.TransferServiceBlockingStub stub =
            TransferServiceGrpc.newBlockingStub(channel);
        TransferResponse resp = stub.transfer(TransferRequest.newBuilder()
            .setFromAccount("SAV2001").setToAccount("CUR3001").setAmount("50000").build());
        log.info(() -> "status=" + resp.getStatus() + " Rajesh=Rs." + resp.getFromBalance());
        channel.shutdown();
    }
}
